class Solution {
public:
    int minimumDistance(vector<vector<int>>& points) {
        int n = points.size();
        vector<int> u(n), v(n);
        for (int i = 0; i < n; ++i) {
            u[i] = points[i][0] + points[i][1];
            v[i] = points[i][0] - points[i][1];
        }

        set<int> candidates;
        int min_u_idx = 0, max_u_idx = 0, min_v_idx = 0, max_v_idx = 0;
        for (int i = 1; i < n; ++i) {
            if (u[i] < u[min_u_idx]) min_u_idx = i;
            if (u[i] > u[max_u_idx]) max_u_idx = i;
            if (v[i] < v[min_v_idx]) min_v_idx = i;
            if (v[i] > v[max_v_idx]) max_v_idx = i;
        }
        candidates.insert(min_u_idx);
        candidates.insert(max_u_idx);
        candidates.insert(min_v_idx);
        candidates.insert(max_v_idx);

        auto max_dist_without = [&](int rem) {
            int max_u = INT_MIN, min_u = INT_MAX;
            int max_v = INT_MIN, min_v = INT_MAX;
            for (int i = 0; i < n; ++i) {
                if (i == rem) continue;
                max_u = max(max_u, u[i]);
                min_u = min(min_u, u[i]);
                max_v = max(max_v, v[i]);
                min_v = min(min_v, v[i]);
            }
            return max(max_u - min_u, max_v - min_v);
        };

        int ans = INT_MAX;
        for (int cand : candidates) {
            ans = min(ans, max_dist_without(cand));
        }
        return ans;
    }
};

class Solution {
    public int minimumDistance(int[][] points) {
        int n = points.length;
        int[] u = new int[n];
        int[] v = new int[n];
        int minU = 0, maxU = 0, minV = 0, maxV = 0;
        for (int i = 0; i < n; i++) {
            u[i] = points[i][0] + points[i][1];
            v[i] = points[i][0] - points[i][1];
            if (u[i] < u[minU]) minU = i;
            if (u[i] > u[maxU]) maxU = i;
            if (v[i] < v[minV]) minV = i;
            if (v[i] > v[maxV]) maxV = i;
        }

        Set<Integer> candidates = new HashSet<>(Arrays.asList(minU, maxU, minV, maxV));
        int ans = Integer.MAX_VALUE;
        for (int cand : candidates) {
            int mxU = Integer.MIN_VALUE, mnU = Integer.MAX_VALUE;
            int mxV = Integer.MIN_VALUE, mnV = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                if (i == cand) continue;
                mxU = Math.max(mxU, u[i]);
                mnU = Math.min(mnU, u[i]);
                mxV = Math.max(mxV, v[i]);
                mnV = Math.min(mnV, v[i]);
            }
            ans = Math.min(ans, Math.max(mxU - mnU, mxV - mnV));
        }
        return ans;
    }
}

var minimumDistance = function(points) {
    const n = points.length;
    const u = new Array(n), v = new Array(n);
    let minU = 0, maxU = 0, minV = 0, maxV = 0;
    for (let i = 0; i < n; i++) {
        u[i] = points[i][0] + points[i][1];
        v[i] = points[i][0] - points[i][1];
        if (u[i] < u[minU]) minU = i;
        if (u[i] > u[maxU]) maxU = i;
        if (v[i] < v[minV]) minV = i;
        if (v[i] > v[maxV]) maxV = i;
    }

    const candidates = new Set([minU, maxU, minV, maxV]);
    let ans = Infinity;
    for (const cand of candidates) {
        let mxU = -Infinity, mnU = Infinity;
        let mxV = -Infinity, mnV = Infinity;
        for (let i = 0; i < n; i++) {
            if (i === cand) continue;
            if (u[i] > mxU) mxU = u[i];
            if (u[i] < mnU) mnU = u[i];
            if (v[i] > mxV) mxV = v[i];
            if (v[i] < mnV) mnV = v[i];
        }
        ans = Math.min(ans, Math.max(mxU - mnU, mxV - mnV));
    }
    return ans;
};
